-- Baseline schema (public schema only).
--
-- Dumped from the production project with
-- `npx supabase db dump --linked --schema public` on 2026-10-18. It replaces
-- the ten earlier migrations, which could not build an empty database because
-- the projects and images tables were first created in the dashboard.
-- Supabase's platform-managed rls_auto_enable() function is left out.
-- Do not edit this file; add schema changes as new migrations.
--
-- Recycle Bin: deleting a project or image moves it into recycle_bin_items,
-- which holds a JSON snapshot of the deleted rows. The live rows are deleted
-- (FK cascades clean up annotation jobs). S3 objects are kept until the item
-- is deleted permanently; that step lives in lib/recycle-bin.ts because only
-- the app holds S3 credentials. Items are retained for 30 days. Only
-- move_project_to_recycle_bin and move_images_to_recycle_bin can insert rows:
-- they set the transaction-local app.recycle_bin_writer setting that the
-- INSERT policy requires.
--
-- Error contract (SQLSTATE / message) consumed by lib/actions/recycle-bin.ts:
--   RB001 NOT_AUTHENTICATED
--   RB002 PROJECT_NOT_FOUND           project missing/not owned (move), or permanently gone (restore image)
--   RB003 IMAGES_NOT_FOUND            an image id is not in the owned project (all-or-nothing)
--   RB004 RECYCLE_BIN_ITEM_NOT_FOUND  trash row missing, not owned, or already restored/deleted
--   RB005 PROJECT_IN_RECYCLE_BIN      restoring an image whose project is itself in the bin
--   RB006 RESTORE_CONFLICT            a live row with the same id already exists
--   RB007 RECYCLE_BIN_SNAPSHOT_INVALID
--   RB008 RECYCLE_BIN_ITEM_DELETING   permanent deletion started (files may be partly gone)
--   RB009 RECYCLE_BIN_ITEM_EXPIRED    past its 30-day retention, awaiting purge

SET statement_timeout = 0;
SET lock_timeout = 0;
SET idle_in_transaction_session_timeout = 0;
SET client_encoding = 'UTF8';
SET standard_conforming_strings = on;
SELECT pg_catalog.set_config('search_path', '', false);
SET check_function_bodies = false;
SET xmloption = content;
SET client_min_messages = warning;
SET row_security = off;

CREATE SCHEMA IF NOT EXISTS "public";

ALTER SCHEMA "public" OWNER TO "pg_database_owner";

COMMENT ON SCHEMA "public" IS 'standard public schema';

CREATE OR REPLACE FUNCTION "public"."annotation_image_states"("p_project_id" "uuid") RETURNS TABLE("image_id" "uuid", "status" "text", "pending_suggestions" integer)
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'public'
    AS $$
  select latest.image_id,
         latest.status,
         coalesce((
           select sum(pending.suggestion_count)::integer
           from annotation_job_items as pending
           where pending.project_id = p_project_id
             and pending.image_id = latest.image_id
             and pending.suggestion_count > 0
         ), 0)
  from (
    select distinct on (item.image_id) item.image_id, item.status
    from annotation_job_items as item
    where item.project_id = p_project_id
    order by item.image_id, item.created_at desc
  ) as latest;
$$;

ALTER FUNCTION "public"."annotation_image_states"("p_project_id" "uuid") OWNER TO "postgres";

CREATE OR REPLACE FUNCTION "public"."annotation_job_counts"("p_job_id" "uuid") RETURNS TABLE("status" "text", "items" integer, "suggestions" integer)
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'public'
    AS $$
  select item.status, count(*)::integer, coalesce(sum(item.suggestion_count), 0)::integer
  from annotation_job_items as item
  where item.job_id = p_job_id
  group by item.status;
$$;

ALTER FUNCTION "public"."annotation_job_counts"("p_job_id" "uuid") OWNER TO "postgres";

SET default_tablespace = '';

SET default_table_access_method = "heap";

CREATE TABLE IF NOT EXISTS "public"."annotation_job_items" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "job_id" "uuid" NOT NULL,
    "project_id" "uuid" NOT NULL,
    "image_id" "uuid" NOT NULL,
    "position" integer NOT NULL,
    "status" "text" DEFAULT 'queued'::"text" NOT NULL,
    "attempts" integer DEFAULT 0 NOT NULL,
    "locked_until" timestamp with time zone,
    "error" "text",
    "suggestions" "jsonb" DEFAULT '[]'::"jsonb" NOT NULL,
    "suggestion_count" integer GENERATED ALWAYS AS ("jsonb_array_length"("suggestions")) STORED,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "completed_at" timestamp with time zone,
    CONSTRAINT "annotation_job_items_status_check" CHECK (("status" = ANY (ARRAY['queued'::"text", 'running'::"text", 'succeeded'::"text", 'failed'::"text", 'cancelled'::"text"])))
);

ALTER TABLE "public"."annotation_job_items" OWNER TO "postgres";

CREATE OR REPLACE FUNCTION "public"."claim_annotation_job_items"("p_project_id" "uuid", "p_limit" integer, "p_lock_seconds" integer DEFAULT 90) RETURNS SETOF "public"."annotation_job_items"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
begin
  -- Items whose lease expired after the final attempt (worker died) fail.
  update annotation_job_items
  set status = 'failed',
      error = coalesce(error, 'Timed out after repeated attempts.'),
      locked_until = null,
      updated_at = now()
  where project_id = p_project_id
    and status = 'running'
    and locked_until < now()
    and attempts >= 3;

  return query
  update annotation_job_items as item
  set status = 'running',
      attempts = item.attempts + 1,
      locked_until = now() + make_interval(secs => p_lock_seconds),
      updated_at = now()
  where item.id in (
    select candidate.id
    from annotation_job_items as candidate
    join annotation_jobs as job on job.id = candidate.job_id
    where candidate.project_id = p_project_id
      and job.status in ('queued', 'running')
      and (
        (candidate.status = 'queued'
          and (candidate.locked_until is null or candidate.locked_until < now()))
        or (candidate.status = 'running' and candidate.locked_until < now())
      )
    order by candidate.position
    for update of candidate skip locked
    limit p_limit
  )
  returning item.*;
end;
$$;

ALTER FUNCTION "public"."claim_annotation_job_items"("p_project_id" "uuid", "p_limit" integer, "p_lock_seconds" integer) OWNER TO "postgres";

CREATE OR REPLACE FUNCTION "public"."finalize_annotation_jobs"("p_project_id" "uuid") RETURNS "void"
    LANGUAGE "sql"
    SET "search_path" TO 'public'
    AS $$
  update annotation_jobs as job
  set status = 'completed', finished_at = now(), updated_at = now()
  where job.project_id = p_project_id
    and job.status in ('queued', 'running')
    and not exists (
      select 1 from annotation_job_items as item
      where item.job_id = job.id
        and item.status in ('queued', 'running')
    );
$$;

ALTER FUNCTION "public"."finalize_annotation_jobs"("p_project_id" "uuid") OWNER TO "postgres";

CREATE OR REPLACE FUNCTION "public"."move_images_to_recycle_bin"("p_project_id" "uuid", "p_image_ids" "uuid"[]) RETURNS "uuid"[]
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
declare
  v_user_id uuid := auth.uid();
  v_project_name text;
  v_image_ids uuid[];
  v_found integer;
  v_item_ids uuid[];
begin
  if v_user_id is null then
    raise exception 'NOT_AUTHENTICATED' using errcode = 'RB001';
  end if;

  select coalesce(array_agg(distinct requested.id), '{}'::uuid[])
  into v_image_ids
  from unnest(p_image_ids) as requested(id)
  where requested.id is not null;

  if cardinality(v_image_ids) = 0 then
    raise exception 'IMAGES_NOT_FOUND'
      using errcode = 'RB003', detail = 'Select at least one image.';
  end if;

  -- KEY SHARE serialises with move_project_to_recycle_bin (FOR UPDATE).
  select name into v_project_name
  from projects
  where id = p_project_id
    and user_id = v_user_id
  for key share;

  if not found then
    raise exception 'PROJECT_NOT_FOUND'
      using errcode = 'RB002',
            detail = 'The project does not exist or you do not have access.';
  end if;

  select count(*)::integer
  into v_found
  from (
    select 1
    from images
    where project_id = p_project_id
      and id = any(v_image_ids)
    for update
  ) as locked;

  if v_found <> cardinality(v_image_ids) then
    raise exception 'IMAGES_NOT_FOUND'
      using errcode = 'RB003',
            detail = 'One or more images do not belong to this project.';
  end if;

  perform set_config('app.recycle_bin_writer', 'on', true);
  with inserted as (
    insert into recycle_bin_items (
      user_id, kind, project_id, image_id, name, project_name,
      image_count, size_bytes, object_keys, snapshot
    )
    select
      v_user_id, 'image', image.project_id, image.id, image.name, v_project_name,
      1, image.size_bytes, array[image.object_key],
      jsonb_build_object(
        'image', to_jsonb(image),
        'labels', coalesce((
          select jsonb_agg(
                   jsonb_build_object('id', label.id, 'name', label.name, 'color', label.color)
                   order by label.created_at, label.id
                 )
          from project_labels as label
          where label.project_id = image.project_id
            and label.id::text in (
              select box ->> 'labelId'
              from jsonb_array_elements(
                     case when jsonb_typeof(image.annotation) = 'array'
                          then image.annotation
                          else '[]'::jsonb end
                   ) as element(box)
              where jsonb_typeof(box) = 'object'
            )
        ), '[]'::jsonb)
      )
    from images as image
    where image.project_id = p_project_id
      and image.id = any(v_image_ids)
    returning id
  )
  select array_agg(id) into v_item_ids from inserted;
  perform set_config('app.recycle_bin_writer', 'off', true);

  delete from images
  where project_id = p_project_id
    and id = any(v_image_ids);

  return v_item_ids;
end;
$$;

ALTER FUNCTION "public"."move_images_to_recycle_bin"("p_project_id" "uuid", "p_image_ids" "uuid"[]) OWNER TO "postgres";

CREATE OR REPLACE FUNCTION "public"."move_project_to_recycle_bin"("p_project_id" "uuid") RETURNS "uuid"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
declare
  v_user_id uuid := auth.uid();
  v_project projects;
  v_labels jsonb;
  v_images jsonb;
  v_image_count integer;
  v_size_bytes bigint;
  v_object_keys text[];
  v_item_id uuid;
begin
  if v_user_id is null then
    raise exception 'NOT_AUTHENTICATED' using errcode = 'RB001';
  end if;

  -- FOR UPDATE also blocks concurrent image/label inserts (their FK checks
  -- take KEY SHARE on this row) until the move commits.
  select * into v_project
  from projects
  where id = p_project_id
    and user_id = v_user_id
  for update;

  if not found then
    raise exception 'PROJECT_NOT_FOUND'
      using errcode = 'RB002',
            detail = 'The project does not exist or you do not have access.';
  end if;

  -- Concurrent annotation saves either land before the snapshot or fail
  -- after the move instead of being silently lost.
  perform 1 from images where project_id = p_project_id for update;
  perform 1 from project_labels where project_id = p_project_id for update;

  select coalesce(jsonb_agg(to_jsonb(label) order by label.created_at, label.id), '[]'::jsonb)
  into v_labels
  from project_labels as label
  where label.project_id = p_project_id;

  select coalesce(jsonb_agg(to_jsonb(image) order by image.created_at, image.id), '[]'::jsonb),
         count(*)::integer,
         coalesce(sum(image.size_bytes), 0)::bigint,
         coalesce(array_agg(image.object_key order by image.created_at, image.id), '{}'::text[])
  into v_images, v_image_count, v_size_bytes, v_object_keys
  from images as image
  where image.project_id = p_project_id;

  perform set_config('app.recycle_bin_writer', 'on', true);
  insert into recycle_bin_items (
    user_id, kind, project_id, name, project_name, description,
    image_count, size_bytes, object_keys, snapshot
  )
  values (
    v_user_id, 'project', v_project.id, v_project.name, v_project.name, v_project.description,
    v_image_count, v_size_bytes, v_object_keys,
    jsonb_build_object('project', to_jsonb(v_project), 'labels', v_labels, 'images', v_images)
  )
  returning id into v_item_id;
  perform set_config('app.recycle_bin_writer', 'off', true);

  -- Explicit child deletes (rather than relying on cascades) mirror
  -- deleteProject(); annotation jobs and job items still cascade.
  delete from images where project_id = p_project_id;
  delete from project_labels where project_id = p_project_id;
  delete from projects where id = p_project_id;

  return v_item_id;
end;
$$;

ALTER FUNCTION "public"."move_project_to_recycle_bin"("p_project_id" "uuid") OWNER TO "postgres";

CREATE OR REPLACE FUNCTION "public"."restore_recycle_bin_item"("p_item_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $_$
declare
  v_user_id uuid := auth.uid();
  v_item recycle_bin_items;
  v_project_rows jsonb := '[]'::jsonb;
  v_label_rows jsonb := '[]'::jsonb;
  v_image_rows jsonb := '[]'::jsonb;
  v_image jsonb;
  v_label record;
  v_label_map jsonb := '{}'::jsonb;
  v_label_id uuid;
  v_table regclass;
  v_rows jsonb;
  v_columns text;
begin
  if v_user_id is null then
    raise exception 'NOT_AUTHENTICATED' using errcode = 'RB001';
  end if;

  -- Deleting first claims the item: a concurrent restore or deletion mark
  -- waits on the row lock, and under READ COMMITTED this WHERE clause is
  -- re-checked against the committed row, so a row marked for permanent
  -- deletion (or expired) is never restored. Any later error rolls this back.
  delete from recycle_bin_items
  where id = p_item_id
    and user_id = v_user_id
    and purge_started_at is null
    and expires_at > now()
  returning * into v_item;

  if not found then
    if exists (
      select 1 from recycle_bin_items
      where id = p_item_id
        and user_id = v_user_id
        and purge_started_at is not null
    ) then
      raise exception 'RECYCLE_BIN_ITEM_DELETING' using errcode = 'RB008';
    elsif exists (
      select 1 from recycle_bin_items
      where id = p_item_id
        and user_id = v_user_id
    ) then
      raise exception 'RECYCLE_BIN_ITEM_EXPIRED' using errcode = 'RB009';
    end if;
    raise exception 'RECYCLE_BIN_ITEM_NOT_FOUND' using errcode = 'RB004';
  end if;

  if v_item.kind = 'project' then
    if jsonb_typeof(v_item.snapshot -> 'project') is distinct from 'object' then
      raise exception 'RECYCLE_BIN_SNAPSHOT_INVALID' using errcode = 'RB007';
    end if;
    if exists (select 1 from projects where id = v_item.project_id) then
      raise exception 'RESTORE_CONFLICT'
        using errcode = 'RB006', detail = 'A project with this id already exists.';
    end if;

    -- Same id and timestamps; ownership is always the restoring user.
    v_project_rows := jsonb_build_array(
      (v_item.snapshot -> 'project') || jsonb_build_object('user_id', v_user_id)
    );
    v_label_rows := coalesce(v_item.snapshot -> 'labels', '[]'::jsonb);
    v_image_rows := coalesce(v_item.snapshot -> 'images', '[]'::jsonb);
  else
    v_image := v_item.snapshot -> 'image';
    if jsonb_typeof(v_image) is distinct from 'object' then
      raise exception 'RECYCLE_BIN_SNAPSHOT_INVALID' using errcode = 'RB007';
    end if;

    -- KEY SHARE waits for an in-flight move_project_to_recycle_bin.
    perform 1 from projects
    where id = v_item.project_id
      and user_id = v_user_id
    for key share;

    if not found then
      if exists (
        select 1 from recycle_bin_items
        where kind = 'project'
          and project_id = v_item.project_id
          and purge_started_at is null
      ) then
        raise exception 'PROJECT_IN_RECYCLE_BIN'
          using errcode = 'RB005', detail = v_item.project_name;
      end if;
      raise exception 'PROJECT_NOT_FOUND'
        using errcode = 'RB002', detail = 'The project was permanently deleted.';
    end if;

    if exists (select 1 from images where id = v_item.image_id) then
      raise exception 'RESTORE_CONFLICT'
        using errcode = 'RB006', detail = 'An image with this id already exists.';
    end if;

    -- Map each snapshot label onto the project: same id, else same
    -- case/space-insensitive name, else recreate it (keeping its id if free).
    for v_label in
      select snapshot_label.id, snapshot_label.name, snapshot_label.color
      from jsonb_to_recordset(
             case when jsonb_typeof(v_item.snapshot -> 'labels') = 'array'
                  then v_item.snapshot -> 'labels'
                  else '[]'::jsonb end
           ) as snapshot_label(id text, name text, color text)
    loop
      continue when v_label.id is null or coalesce(trim(v_label.name), '') = '';

      v_label_id := null;
      select label.id into v_label_id
      from project_labels as label
      where label.project_id = v_item.project_id
        and label.id::text = v_label.id;

      if v_label_id is null then
        select label.id into v_label_id
        from project_labels as label
        where label.project_id = v_item.project_id
          and lower(trim(label.name)) = lower(trim(v_label.name))
        order by label.created_at, label.id
        limit 1;
      end if;

      if v_label_id is null then
        v_label_id := gen_random_uuid();
        if v_label.id ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' then
          if not exists (select 1 from project_labels where id = v_label.id::uuid) then
            v_label_id := v_label.id::uuid;
          end if;
        end if;

        -- A parallel restore may be recreating the same label right now:
        -- ON CONFLICT waits for it, then the lookup below reuses its row.
        insert into project_labels (id, project_id, name, color)
        values (
          v_label_id,
          v_item.project_id,
          trim(v_label.name),
          coalesce(nullif(v_label.color, ''), '#2563eb')
        )
        on conflict do nothing
        returning id into v_label_id;

        if v_label_id is null then
          select label.id into v_label_id
          from project_labels as label
          where label.project_id = v_item.project_id
            and lower(trim(label.name)) = lower(trim(v_label.name))
          order by label.created_at, label.id
          limit 1;
        end if;

        if v_label_id is null then
          -- The conflict was on the id (taken in the meantime), not the name.
          insert into project_labels (project_id, name, color)
          values (
            v_item.project_id,
            trim(v_label.name),
            coalesce(nullif(v_label.color, ''), '#2563eb')
          )
          returning id into v_label_id;
        end if;
      end if;

      v_label_map := v_label_map || jsonb_build_object(v_label.id, v_label_id::text);
    end loop;

    if jsonb_typeof(v_image -> 'annotation') = 'array' then
      v_image := jsonb_set(v_image, '{annotation}', (
        select coalesce(jsonb_agg(
                 case
                   when jsonb_typeof(element.box) = 'object'
                    and v_label_map ? (element.box ->> 'labelId')
                   then jsonb_set(element.box, '{labelId}', v_label_map -> (element.box ->> 'labelId'))
                   else element.box
                 end
                 order by element.ord
               ), '[]'::jsonb)
        from jsonb_array_elements(v_image -> 'annotation') with ordinality as element(box, ord)
      ));
    end if;

    v_image_rows := jsonb_build_array(
      v_image || jsonb_build_object('project_id', v_item.project_id)
    );
  end if;

  -- Re-insert the snapshot rows against the live table row types. Only
  -- columns present in the snapshot are written, so columns added after the
  -- snapshot fall back to their defaults and generated columns are skipped.
  for v_table, v_rows in
    select batch.target, batch.rows_json
    from (values
      (1, 'public.projects'::regclass, v_project_rows),
      (2, 'public.project_labels'::regclass, v_label_rows),
      (3, 'public.images'::regclass, v_image_rows)
    ) as batch(ord, target, rows_json)
    where case when jsonb_typeof(batch.rows_json) = 'array'
               then jsonb_array_length(batch.rows_json) > 0
               else false end
    order by batch.ord
  loop
    select string_agg(quote_ident(attribute.attname), ', ' order by attribute.attnum)
    into v_columns
    from pg_attribute as attribute
    where attribute.attrelid = v_table
      and attribute.attnum > 0
      and not attribute.attisdropped
      and attribute.attgenerated = ''
      and attribute.attidentity <> 'a'
      and (v_rows -> 0) ? attribute.attname::text;

    if v_columns is null then
      raise exception 'RECYCLE_BIN_SNAPSHOT_INVALID' using errcode = 'RB007';
    end if;

    execute format(
      'insert into %s (%s) select %s from jsonb_populate_recordset(null::%s, $1)',
      v_table, v_columns, v_columns, v_table
    ) using v_rows;
  end loop;

  return jsonb_strip_nulls(jsonb_build_object(
    'kind', v_item.kind,
    'itemId', v_item.id,
    'projectId', v_item.project_id,
    'imageId', v_item.image_id
  ));
end;
$_$;

ALTER FUNCTION "public"."restore_recycle_bin_item"("p_item_id" "uuid") OWNER TO "postgres";

CREATE OR REPLACE FUNCTION "public"."set_projects_updated_at"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
begin
  new.updated_at = now();
  return new;
end;
$$;

ALTER FUNCTION "public"."set_projects_updated_at"() OWNER TO "postgres";

CREATE TABLE IF NOT EXISTS "public"."annotation_jobs" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "project_id" "uuid" NOT NULL,
    "user_id" "uuid" DEFAULT "auth"."uid"() NOT NULL,
    "status" "text" DEFAULT 'queued'::"text" NOT NULL,
    "labels" "jsonb" NOT NULL,
    "confidence" real NOT NULL,
    "total_items" integer NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "finished_at" timestamp with time zone,
    CONSTRAINT "annotation_jobs_confidence_check" CHECK ((("confidence" >= (0)::double precision) AND ("confidence" <= (1)::double precision))),
    CONSTRAINT "annotation_jobs_status_check" CHECK (("status" = ANY (ARRAY['queued'::"text", 'running'::"text", 'completed'::"text", 'cancelled'::"text"]))),
    CONSTRAINT "annotation_jobs_total_items_check" CHECK (("total_items" > 0))
);

ALTER TABLE "public"."annotation_jobs" OWNER TO "postgres";

CREATE TABLE IF NOT EXISTS "public"."images" (
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "modified_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "name" "text" NOT NULL,
    "notes" "text",
    "url" "text",
    "annotation" "jsonb",
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "project_id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "object_key" "text" NOT NULL,
    "content_type" "text" NOT NULL,
    "size_bytes" bigint NOT NULL,
    "thumbhash" "text",
    CONSTRAINT "images_content_type_check" CHECK (("content_type" = ANY (ARRAY['image/jpeg'::"text", 'image/png'::"text"]))),
    CONSTRAINT "images_size_bytes_check" CHECK (("size_bytes" > 0))
);

ALTER TABLE "public"."images" OWNER TO "postgres";

COMMENT ON TABLE "public"."images" IS 'Table contains image urls and metadata of annotations';

CREATE TABLE IF NOT EXISTS "public"."project_labels" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "project_id" "uuid" NOT NULL,
    "name" "text" NOT NULL,
    "color" "text" NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL
);

ALTER TABLE "public"."project_labels" OWNER TO "postgres";

CREATE TABLE IF NOT EXISTS "public"."projects" (
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "modified_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "owner_id" "uuid" DEFAULT "auth"."uid"(),
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "description" "text",
    "starred" boolean DEFAULT false NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "user_id" "uuid" NOT NULL,
    "name" "text" NOT NULL
);

ALTER TABLE "public"."projects" OWNER TO "postgres";

COMMENT ON TABLE "public"."projects" IS 'This table contains project details including user ownership';

CREATE TABLE IF NOT EXISTS "public"."recycle_bin_items" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "user_id" "uuid" DEFAULT "auth"."uid"() NOT NULL,
    "kind" "text" NOT NULL,
    "project_id" "uuid" NOT NULL,
    "image_id" "uuid",
    "name" "text" NOT NULL,
    "project_name" "text" NOT NULL,
    "description" "text",
    "image_count" integer DEFAULT 0 NOT NULL,
    "size_bytes" bigint DEFAULT 0 NOT NULL,
    "object_keys" "text"[] DEFAULT '{}'::"text"[] NOT NULL,
    "cover_object_key" "text" GENERATED ALWAYS AS ("object_keys"[1]) STORED,
    "snapshot" "jsonb" NOT NULL,
    "deleted_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "expires_at" timestamp with time zone GENERATED ALWAYS AS (((("deleted_at" AT TIME ZONE 'UTC'::"text") + '30 days'::interval) AT TIME ZONE 'UTC'::"text")) STORED,
    "purge_started_at" timestamp with time zone,
    CONSTRAINT "recycle_bin_items_image_count_check" CHECK (("image_count" >= 0)),
    CONSTRAINT "recycle_bin_items_image_id_matches_kind" CHECK ((("kind" = 'image'::"text") = ("image_id" IS NOT NULL))),
    CONSTRAINT "recycle_bin_items_kind_check" CHECK (("kind" = ANY (ARRAY['project'::"text", 'image'::"text"]))),
    CONSTRAINT "recycle_bin_items_size_bytes_check" CHECK (("size_bytes" >= 0))
);

ALTER TABLE "public"."recycle_bin_items" OWNER TO "postgres";

ALTER TABLE ONLY "public"."annotation_job_items"
    ADD CONSTRAINT "annotation_job_items_job_id_image_id_key" UNIQUE ("job_id", "image_id");

ALTER TABLE ONLY "public"."annotation_job_items"
    ADD CONSTRAINT "annotation_job_items_pkey" PRIMARY KEY ("id");

ALTER TABLE ONLY "public"."annotation_jobs"
    ADD CONSTRAINT "annotation_jobs_id_project_id_key" UNIQUE ("id", "project_id");

ALTER TABLE ONLY "public"."annotation_jobs"
    ADD CONSTRAINT "annotation_jobs_pkey" PRIMARY KEY ("id");

ALTER TABLE ONLY "public"."images"
    ADD CONSTRAINT "images_object_key_key" UNIQUE ("object_key");

ALTER TABLE ONLY "public"."images"
    ADD CONSTRAINT "images_pkey" PRIMARY KEY ("id");

ALTER TABLE ONLY "public"."project_labels"
    ADD CONSTRAINT "project_labels_pkey" PRIMARY KEY ("id");

ALTER TABLE ONLY "public"."projects"
    ADD CONSTRAINT "projects_pkey" PRIMARY KEY ("id");

ALTER TABLE ONLY "public"."recycle_bin_items"
    ADD CONSTRAINT "recycle_bin_items_pkey" PRIMARY KEY ("id");

CREATE INDEX "annotation_job_items_claim_idx" ON "public"."annotation_job_items" USING "btree" ("project_id", "position") WHERE ("status" = ANY (ARRAY['queued'::"text", 'running'::"text"]));

CREATE INDEX "annotation_job_items_job_updated_idx" ON "public"."annotation_job_items" USING "btree" ("job_id", "updated_at");

CREATE INDEX "annotation_job_items_pending_review_idx" ON "public"."annotation_job_items" USING "btree" ("project_id", "image_id") WHERE ("suggestion_count" > 0);

CREATE UNIQUE INDEX "annotation_jobs_one_active_per_project_idx" ON "public"."annotation_jobs" USING "btree" ("project_id") WHERE ("status" = ANY (ARRAY['queued'::"text", 'running'::"text"]));

CREATE INDEX "annotation_jobs_project_id_created_at_idx" ON "public"."annotation_jobs" USING "btree" ("project_id", "created_at" DESC);

CREATE INDEX "images_project_id_created_at_idx" ON "public"."images" USING "btree" ("project_id", "created_at");

CREATE INDEX "project_labels_project_id_idx" ON "public"."project_labels" USING "btree" ("project_id");

CREATE UNIQUE INDEX "project_labels_project_id_lower_name_idx" ON "public"."project_labels" USING "btree" ("project_id", "lower"("name"));

CREATE UNIQUE INDEX "recycle_bin_items_one_image_idx" ON "public"."recycle_bin_items" USING "btree" ("image_id") WHERE ("kind" = 'image'::"text");

CREATE UNIQUE INDEX "recycle_bin_items_one_project_idx" ON "public"."recycle_bin_items" USING "btree" ("project_id") WHERE ("kind" = 'project'::"text");

CREATE INDEX "recycle_bin_items_project_id_idx" ON "public"."recycle_bin_items" USING "btree" ("project_id");

CREATE INDEX "recycle_bin_items_user_expires_at_idx" ON "public"."recycle_bin_items" USING "btree" ("user_id", "expires_at");

CREATE INDEX "recycle_bin_items_user_kind_deleted_at_idx" ON "public"."recycle_bin_items" USING "btree" ("user_id", "kind", "deleted_at" DESC);

CREATE OR REPLACE TRIGGER "projects_updated_at" BEFORE UPDATE ON "public"."projects" FOR EACH ROW EXECUTE FUNCTION "public"."set_projects_updated_at"();

ALTER TABLE ONLY "public"."annotation_job_items"
    ADD CONSTRAINT "annotation_job_items_image_id_fkey" FOREIGN KEY ("image_id") REFERENCES "public"."images"("id") ON DELETE CASCADE;

ALTER TABLE ONLY "public"."annotation_job_items"
    ADD CONSTRAINT "annotation_job_items_job_id_project_id_fkey" FOREIGN KEY ("job_id", "project_id") REFERENCES "public"."annotation_jobs"("id", "project_id") ON DELETE CASCADE;

ALTER TABLE ONLY "public"."annotation_jobs"
    ADD CONSTRAINT "annotation_jobs_project_id_fkey" FOREIGN KEY ("project_id") REFERENCES "public"."projects"("id") ON DELETE CASCADE;

ALTER TABLE ONLY "public"."annotation_jobs"
    ADD CONSTRAINT "annotation_jobs_user_id_fkey" FOREIGN KEY ("user_id") REFERENCES "auth"."users"("id") ON DELETE CASCADE;

ALTER TABLE ONLY "public"."images"
    ADD CONSTRAINT "images_project_id_fkey" FOREIGN KEY ("project_id") REFERENCES "public"."projects"("id") ON UPDATE CASCADE ON DELETE CASCADE;

ALTER TABLE ONLY "public"."project_labels"
    ADD CONSTRAINT "project_labels_project_id_fkey" FOREIGN KEY ("project_id") REFERENCES "public"."projects"("id") ON DELETE CASCADE;

ALTER TABLE ONLY "public"."projects"
    ADD CONSTRAINT "projects_owner_id_fkey" FOREIGN KEY ("owner_id") REFERENCES "auth"."users"("id") ON UPDATE CASCADE ON DELETE CASCADE;

