    ADD CONSTRAINT "projects_user_id_fkey" FOREIGN KEY ("user_id") REFERENCES "auth"."users"("id");

ALTER TABLE ONLY "public"."recycle_bin_items"
    ADD CONSTRAINT "recycle_bin_items_user_id_fkey" FOREIGN KEY ("user_id") REFERENCES "auth"."users"("id") ON DELETE CASCADE;

CREATE POLICY "Users can delete images in own projects" ON "public"."images" FOR DELETE USING ((EXISTS ( SELECT 1
   FROM "public"."projects"
  WHERE (("projects"."id" = "images"."project_id") AND ("projects"."user_id" = "auth"."uid"())))));

CREATE POLICY "Users can delete labels in own projects" ON "public"."project_labels" FOR DELETE USING ((EXISTS ( SELECT 1
   FROM "public"."projects"
  WHERE (("projects"."id" = "project_labels"."project_id") AND ("projects"."user_id" = "auth"."uid"())))));

CREATE POLICY "Users can delete own projects" ON "public"."projects" FOR DELETE USING (("auth"."uid"() = "user_id"));

CREATE POLICY "Users can delete own recycle bin items" ON "public"."recycle_bin_items" FOR DELETE USING (("user_id" = ( SELECT "auth"."uid"() AS "uid")));

CREATE POLICY "Users can insert images in own projects" ON "public"."images" FOR INSERT WITH CHECK ((EXISTS ( SELECT 1
   FROM "public"."projects"
  WHERE (("projects"."id" = "images"."project_id") AND ("projects"."user_id" = "auth"."uid"())))));

CREATE POLICY "Users can insert labels in own projects" ON "public"."project_labels" FOR INSERT WITH CHECK ((EXISTS ( SELECT 1
   FROM "public"."projects"
  WHERE (("projects"."id" = "project_labels"."project_id") AND ("projects"."user_id" = "auth"."uid"())))));

CREATE POLICY "Users can insert own projects" ON "public"."projects" FOR INSERT WITH CHECK (("auth"."uid"() = "user_id"));

CREATE POLICY "Users can insert own recycle bin items" ON "public"."recycle_bin_items" FOR INSERT WITH CHECK ((("user_id" = ( SELECT "auth"."uid"() AS "uid")) AND ("current_setting"('app.recycle_bin_writer'::"text", true) = 'on'::"text")));

CREATE POLICY "Users can mark own recycle bin items for deletion" ON "public"."recycle_bin_items" FOR UPDATE USING (("user_id" = ( SELECT "auth"."uid"() AS "uid"))) WITH CHECK ((("user_id" = ( SELECT "auth"."uid"() AS "uid")) AND ("purge_started_at" IS NOT NULL)));

CREATE POLICY "Users can update images in own projects" ON "public"."images" FOR UPDATE USING ((EXISTS ( SELECT 1
   FROM "public"."projects"
  WHERE (("projects"."id" = "images"."project_id") AND ("projects"."user_id" = "auth"."uid"()))))) WITH CHECK ((EXISTS ( SELECT 1
   FROM "public"."projects"
  WHERE (("projects"."id" = "images"."project_id") AND ("projects"."user_id" = "auth"."uid"())))));

CREATE POLICY "Users can update labels in own projects" ON "public"."project_labels" FOR UPDATE USING ((EXISTS ( SELECT 1
   FROM "public"."projects"
  WHERE (("projects"."id" = "project_labels"."project_id") AND ("projects"."user_id" = "auth"."uid"()))))) WITH CHECK ((EXISTS ( SELECT 1
   FROM "public"."projects"
  WHERE (("projects"."id" = "project_labels"."project_id") AND ("projects"."user_id" = "auth"."uid"())))));

CREATE POLICY "Users can update own projects" ON "public"."projects" FOR UPDATE USING (("auth"."uid"() = "user_id"));

CREATE POLICY "Users can view images in own projects" ON "public"."images" FOR SELECT USING ((EXISTS ( SELECT 1
   FROM "public"."projects"
  WHERE (("projects"."id" = "images"."project_id") AND ("projects"."user_id" = "auth"."uid"())))));

CREATE POLICY "Users can view labels in own projects" ON "public"."project_labels" FOR SELECT USING ((EXISTS ( SELECT 1
   FROM "public"."projects"
  WHERE (("projects"."id" = "project_labels"."project_id") AND ("projects"."user_id" = "auth"."uid"())))));

CREATE POLICY "Users can view own projects" ON "public"."projects" FOR SELECT USING (("auth"."uid"() = "user_id"));

CREATE POLICY "Users can view own recycle bin items" ON "public"."recycle_bin_items" FOR SELECT USING (("user_id" = ( SELECT "auth"."uid"() AS "uid")));

CREATE POLICY "Users manage annotation job items in own projects" ON "public"."annotation_job_items" USING ((EXISTS ( SELECT 1
   FROM "public"."projects"
  WHERE (("projects"."id" = "annotation_job_items"."project_id") AND ("projects"."user_id" = "auth"."uid"()))))) WITH CHECK ((EXISTS ( SELECT 1
   FROM "public"."projects"
  WHERE (("projects"."id" = "annotation_job_items"."project_id") AND ("projects"."user_id" = "auth"."uid"())))));

CREATE POLICY "Users manage annotation jobs in own projects" ON "public"."annotation_jobs" USING ((EXISTS ( SELECT 1
   FROM "public"."projects"
  WHERE (("projects"."id" = "annotation_jobs"."project_id") AND ("projects"."user_id" = "auth"."uid"()))))) WITH CHECK ((EXISTS ( SELECT 1
   FROM "public"."projects"
  WHERE (("projects"."id" = "annotation_jobs"."project_id") AND ("projects"."user_id" = "auth"."uid"())))));

